import {uid,hash} from './own-payroll-program-synthetic.js';
import {ownNoveltyHash} from '../../lib/internal-own-payroll-novelties.js';
export function subject(n=1){return {contractId:uid(n),legajo:String(1000+n),employeeName:'Persona sintética '+n,identityToken:hash('e'),sourceCutoff:null,origin:'MUNICONTROL',registrationId:uid(10000+n),registeredAt:'2026-10-01T00:00:00Z'};}
export function row(n=1,patch={}){const s=subject(n);return {rowOrdinal:n,contractId:s.contractId,legajo:s.legajo,identityToken:s.identityToken,conceptSourceId:'120',costCenterSourceId:null,adjustmentMonth:null,quantityDecimal:null,amountCents:'2000',movementType:null,legalInstrument:null,observation:null,forced:false,...patch};}
export function prepare(count=2,patch={}){return {command:'prepare',periodMonth:'2026-10-01',payrollType:'monthly',rows:Array.from({length:count},(_,i)=>row(i+1)),reviewConfirmed:true,...patch};}
export function batch(count=2,patch={}){const rows=Array.from({length:count},(_,i)=>({values:row(i+1),subject:subject(i+1),identityCurrent:true}));return {version:'own-payroll-novelty-batch.v1',id:uid(20000),revision:3,status:'approved',periodMonth:'2026-10-01',payrollType:'monthly',rows,rowCount:count,rowsSha256:ownNoveltyHash(rows.map(({values,subject})=>({values,subject}))),preparedBy:{membershipId:uid(21001),personId:uid(21002)},decidedBy:{membershipId:uid(21003),personId:uid(21004)},approvals:[{membershipId:uid(21003),personId:uid(21004)}],grhMutation:false,payrollCalculated:false,payrollPosted:false,...patch};}
export function bootstrap(count=2,patch={}){return {version:'own-payroll-novelty-bootstrap.v1',complete:true,subjects:Array.from({length:count},(_,i)=>subject(i+1)),batches:[],permissions:{canPrepare:true,canApprove:false},...patch};}
export function receipt(body=prepare(),key=uid(23001)){return {version:'own-payroll-novelty-receipt.v1',requestKey:key,requestSha256:ownNoveltyHash(body),body,snapshot:batch(body.rows.length,{revision:1,status:'draft',decidedBy:null,approvals:[]}),replayed:false};}
